from flask import Flask, jsonify, request

app = Flask(__name__)

POSTS = [
    {'id': 1, 'title': 'Intro to Flask'},
    {'id': 2, 'title': 'JSON Basics'},
    {'id': 3, 'title': 'Advanced Patterns'},
    {'id': 4, 'title': 'Testing APIs'}
]

@app.route('/posts')
def get_posts():
    page = request.args.get('page', 1, type=int)
    limit = request.args.get('limit', 2, type=int)
    if page < 1 or limit < 1:
        return jsonify({'error': 'page and limit must be positive integers'}), 400
    start = (page - 1) * limit
    end = start + limit
    paginated = POSTS[start:end]
    return jsonify({'posts': paginated, 'page': page, 'limit': limit, 'total': len(POSTS)})

from flask import Flask, jsonify, request

app = Flask(__name__)

@app.route('/scores/summary', methods=['POST'])
def score_summary():
    data = request.get_json()
    if not data or 'scores' not in data or not isinstance(data['scores'], list):
        return jsonify({'error': 'Invalid input: scores list required'}), 400
    scores = data['scores']
    if not scores:
        return jsonify({'error': 'Scores list cannot be empty'}), 400
    summary = {
        'average': sum(scores) / len(scores),
        'min': min(scores),
        'max': max(scores),
        'count': len(scores)
    }
    return jsonify({'summary': summary})
